const menu=document.querySelector('.menu');const nav=document.querySelector('.nav-links');if(menu&&nav){menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open))})}
const search=document.querySelector('#market-search');const filters=[...document.querySelectorAll('.filter')];const cards=[...document.querySelectorAll('.market-card')];let active='all';function filterMarkets(){if(!cards.length)return;const q=(search?.value||'').trim().toLowerCase();let shown=0;cards.forEach(card=>{const matchesType=active==='all'||card.dataset.type===active;const matchesText=!q||card.textContent.toLowerCase().includes(q);card.hidden=!(matchesType&&matchesText);if(!card.hidden)shown++});const empty=document.querySelector('#market-empty');if(empty)empty.hidden=shown!==0}filters.forEach(btn=>btn.addEventListener('click',()=>{filters.forEach(x=>{x.classList.remove('active');x.setAttribute('aria-pressed','false')});btn.classList.add('active');btn.setAttribute('aria-pressed','true');active=btn.dataset.filter;filterMarkets()}));search?.addEventListener('input',filterMarkets);
document.querySelectorAll('.lead-form').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();const button=form.querySelector('button');const original=button.textContent;button.textContent='You’re on the list';button.disabled=true;form.querySelector('small').textContent='Thanks — connect this form to your email platform before launch to begin collecting leads.';setTimeout(()=>{button.textContent=original;button.disabled=false},5000)}));
